Below is a compact, correct implementation for both parts. Part 1 uses the classic binary-search partition on the smaller array to achieve O(log(min(m,n))). Part 2 implements a streaming median with two heaps (a max-heap implemented via negatives and a min-heap) where add() is O(log n) and median() is O(1).

```python
from typing import List
import heapq
import math


def findMedianSortedArrays(nums1: List[int], nums2: List[int]) -> float:
    """
    Find median of two sorted arrays in O(log(min(m, n))).
    """
    A, B = nums1, nums2
    m, n = len(A), len(B)
    if m > n:  # ensure A is the smaller array
        A, B, m, n = B, A, n, m

    if m == 0:
        if n == 0:
            raise ValueError("Both arrays are empty.")
        # median of single non-empty array B
        mid = n // 2
        if n % 2 == 1:
            return float(B[mid])
        return (B[mid - 1] + B[mid]) / 2.0

    half = (m + n + 1) // 2
    low, high = 0, m

    while low <= high:
        i = (low + high) // 2
        j = half - i

        Aleft = A[i - 1] if i > 0 else -math.inf
        Aright = A[i] if i < m else math.inf
        Bleft = B[j - 1] if j > 0 else -math.inf
        Bright = B[j] if j < n else math.inf

        if Aleft <= Bright and Bleft <= Aright:
            # correct partition
            if (m + n) % 2 == 1:
                return float(max(Aleft, Bleft))
            return (max(Aleft, Bleft) + min(Aright, Bright)) / 2.0
        elif Aleft > Bright:
            high = i - 1
        else:
            low = i + 1

    raise ValueError("Unable to find median (input arrays may not be sorted).")


class StreamingMedian:
    """
    Streaming median using two heaps:
    - _low: max-heap implemented with negatives (contains the lower half)
    - _high: min-heap (contains the upper half)

    add(): O(log n)
    median(): O(1)
    """

    def __init__(self) -> None:
        self._low: List[int] = []   # max-heap via negatives
        self._high: List[int] = []  # min-heap

    def add(self, num: int) -> None:
        if not self._low or num <= -self._low[0]:
            heapq.heappush(self._low, -num)
        else:
            heapq.heappush(self._high, num)

        # Rebalance so that the sizes differ by at most 1
        if len(self._low) > len(self._high) + 1:
            heapq.heappush(self._high, -heapq.heappop(self._low))
        elif len(self._high) > len(self._low) + 1:
            heapq.heappush(self._low, -heapq.heappop(self._high))

    def median(self) -> float:
        if not self._low and not self._high:
            raise ValueError("No elements present.")
        if len(self._low) > len(self._high):
            return float(-self._low[0])
        if len(self._high) > len(self._low):
            return float(self._high[0])
        return (-self._low[0] + self._high[0]) / 2.0


# Example quick tests (can be removed if embedding into a larger project)
if __name__ == "__main__":
    print(findMedianSortedArrays([1, 3], [2]))  # 2.0
    print(findMedianSortedArrays([1, 2], [3, 4]))  # 2.5
    print(findMedianSortedArrays([], [1]))  # 1.0
    print(findMedianSortedArrays([1, 3, 5, 7, 9, 11], [2, 4, 6, 8, 10, 12]))  # 6.5

    sm = StreamingMedian()
    for x in [5, 2, 3, 4, 1, 6]:
        sm.add(x)
        print("added", x, "median", sm.median())
